using NovaHarvest.Core.Models; namespace NovaHarvest.Core.Systems; public sealed class FarmingSystem { readonly Dictionary<string,SeedData> _seeds; readonly Inventory _inventory; public FarmingSystem(IEnumerable<SeedData> seeds,Inventory inventory){_seeds=seeds.ToDictionary(x=>x.SeedItemId);_inventory=inventory;} public bool Plant(FarmPlot plot,string seedId){if(!_seeds.ContainsKey(seedId)||!_inventory.Remove(seedId))return false;if(!plot.Plant(seedId)){_inventory.Add(seedId);return false;}return true;} public bool Water(FarmPlot plot,int day)=>plot.Water(day); public void AdvanceDay(IEnumerable<FarmPlot> plots,int completedDay){foreach(var p in plots)if(p.SeedId is string id&&_seeds.TryGetValue(id,out var s))p.AdvanceDay(completedDay,s);} public bool Harvest(FarmPlot plot,out int amount){amount=0;if(plot.SeedId is not string id||!_seeds.TryGetValue(id,out var s))return false;amount=plot.Harvest(s);if(amount<=0)return false;_inventory.Add(s.CropItemId,amount);return true;} }
